<?php declare(strict_types=1);
$id=max(0,(int)($_GET['id']??0));$supplierId=max(0,(int)($_GET['fornecedor_so']??0));$company=$id>0?$application->adminCompanies()->find($id):null;$supplier=null;if($supplierId>0){try{$supplier=$application->soSuppliers()->findById($supplierId);}catch(\Throwable){}}$adminContent=static function()use($company,$supplier,$supplierId,$csrf):void{if($company===null&&$supplier===null){admin_empty('Empresa não encontrada','Verifique o identificador informado.');return;}if($supplier):?><section class="admin-panel"><h2>Aprovar e cadastrar empresa do SO</h2><form method="post" action="<?=admin_url('actions/empresa-importar-so.php')?>" class="admin-form"><?= $csrf->field() ?><input type="hidden" name="fornecedor_so_id" value="<?= $supplier->id ?>"><label>Nome do fornecedor<input value="<?=admin_h($supplier->name)?>" readonly></label><label>Razão social<input name="razao_social" required value="<?=admin_h($supplier->name)?>"></label><label>Nome fantasia<input name="nome_fantasia"></label><label>Tipo de pessoa<select name="tipo_pessoa" required><option value="juridica">Jurídica</option><option value="fisica">Física</option></select></label><label>Segmento<input name="segmento" required></label><label>Contato responsável<input name="contato_responsavel" value="<?=admin_h($supplier->contact)?>"></label><label>Telefone<input name="telefone" value="<?=admin_h($supplier->phone)?>"></label><label>E-mail<input name="email" type="email"></label><label>Status inicial<select name="status"><option value="pendente">Pendente</option><option value="ativo">Ativa</option></select></label><button class="btn btn-primary">Aprovar e cadastrar</button></form></section><?php else:?><section class="admin-panel"><div class="admin-detail-header"><div><h2><?=admin_h($company['nome_fantasia']??$company['razao_social']??'Empresa')?></h2><?=admin_badge((string)($company['status']??'pendente'))?></div><div class="admin-actions"><form method="post" action="<?=admin_url('actions/empresa-entrar.php')?>"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)$company['id'] ?>"><button class="btn btn-primary" <?=($company['status']??'')==='bloqueado'?'disabled':''?>>Entrar na empresa</button></form><a class="btn btn-outline-secondary" href="<?=admin_url('empresas.php')?>">Voltar</a></div></div><dl class="admin-details"><?php foreach(['razao_social'=>'Razão social','nome_fantasia'=>'Nome fantasia','documento'=>'Documento','segmento'=>'Segmento','contato_responsavel'=>'Contato responsável','telefone'=>'Telefone','email'=>'E-mail','criado_em'=>'Data de cadastro','atualizado_em'=>'Última atualização'] as $key=>$label):?><div><dt><?= $label ?></dt><dd><?=admin_h($company[$key]??'—')?></dd></div><?php endforeach;?></dl><form method="post" action="<?=admin_url('actions/empresa-status.php')?>" class="admin-inline-form"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)$company['id'] ?>"><select name="status"><?php foreach(['pendente'=>'Pendente','ativo'=>'Ativa','inativo'=>'Inativa','bloqueado'=>'Bloqueada'] as $key=>$label):?><option value="<?=$key?>" <?=($company['status']??'')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select><button class="btn btn-outline-primary">Alterar status</button></form></section><?php endif;};
